clc;
clear;
close;
t=-2*pi:0.01:2*pi;
A=2;    % amplitude
f=1;    % //frequency(hz)
x1=A*sin(2*pi*f*t);
x2=A*cos(2*pi*f*t);
subplot(2,1,1); %[output:50ea8ede]
plot(t,x1,'b'); %[output:50ea8ede]
xlabel("time"); %[output:50ea8ede]
ylabel("amplitude"); %[output:50ea8ede]
title("sine wave"); %[output:50ea8ede]
grid on; %[output:50ea8ede]

figure(1);
subplot(2,1,2); %[output:50ea8ede]
plot(t,x2,'r'); %[output:50ea8ede]
xlabel("time"); %[output:50ea8ede]
ylabel("amplitude"); %[output:50ea8ede]
title("cosine wave"); %[output:50ea8ede]
grid on; %[output:50ea8ede]

% // -2pi to 2 pi with increament of 0.01

figure(2); %[output:31bb82e5]
t1=-10:0.01:10;
x3=sin(pi*t1)./(pi*t1); 
x3(t1==0)=1; 
subplot(3,1,1); %[output:31bb82e5]
plot(t1,x3,'r'); %[output:31bb82e5]
xlabel("time"); %[output:31bb82e5]
ylabel("amplitude"); %[output:31bb82e5]
title("sinc function"); %[output:31bb82e5]
grid on; %[output:31bb82e5]


figure(3); %[output:0503ba20]
t2=-2:0.001:2; 
% // sinc(pit1)/pit1
% //trianglar waveform
x4=2*abs(2*(t2-floor(t2+0.5)))-1;
subplot(3,1,2); %[output:0503ba20]
plot(t2,x4,'b'); %[output:0503ba20]
xlabel("time"); %[output:0503ba20]
ylabel("amplitude"); %[output:0503ba20]
title("triangular function"); %[output:0503ba20]
grid on; %[output:0503ba20]

figure(4); %[output:0d76f8f1]
t3=-2:0.001:2; 
% //sawtooth waveform
x5=(2*(t3-floor(t3+0.5)));
subplot(3,1,3); %[output:0d76f8f1]
plot(t3,x5,'r'); %[output:0d76f8f1]
xlabel("time"); %[output:0d76f8f1]
ylabel("amplitude"); %[output:0d76f8f1]
title("sawtooth function"); %[output:0d76f8f1]
grid on %[output:0d76f8f1]

figure(5); %[output:3272732b]
t4=0:0.001:5;
a=-1;
% //decaying exponential
x6=exp(a*t4);
subplot(4,1,1); %[output:3272732b]
plot(t4,x6,'b'); %[output:3272732b]
xlabel("time"); %[output:3272732b]
ylabel("amplitude"); %[output:3272732b]
title("decaying exponential function"); %[output:3272732b]
grid on; %[output:3272732b]

figure(6); %[output:289d8d5c]
t5=0:0.001:5;
a=1.5; 
% //increasing exponential
x7=exp(a*t5);
subplot(5,1,1); %[output:289d8d5c]
plot(t5,x7,'r'); %[output:289d8d5c]
xlabel("time"); %[output:289d8d5c]
ylabel("amplitude"); %[output:289d8d5c]
title("increasing exponential function"); %[output:289d8d5c]
grid on; %[output:289d8d5c]


